mapper.select:
select a.*,e.asset_name as assetName,e.asset_code as code,l.location_name as locationName from ai_alert a
left join equipment_assets e on a.equipment_id = e.asset_id
left join equipment_location l on e.location_id = l.location_id



        and e.asset_code like concat('%', #{data.assetCode}, '%')



        and a.alert_type like concat('%', #{data.alertType}, '%')



        and a.alert_status = #{data.alertStatus}



        and a.alert_time >= #{data.startTime}



        and a.alert_time <= #{data.endTime}


order by a.alert_time desc
